NODE_PATH=$(npm root -g) node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/product_inventory.xlsx');
const ws = wb.Sheets['Products'];
const data = XLSX.utils.sheet_to_json(ws, { header: 1 });

// Expand the header with new columns
data[0] = [
  'Product ID', 'Name', 'Category', 'Price', 'In Stock',
  'Subcategory', 'Brand', 'Stock Quantity', 'Rating', 'Review Count',
  'Description', 'Variants', 'Compatibility', 'Shipping Days',
  'Gift Wrap Available', 'Backorder Available', 'Warranty (Months)',
  'Return Window (Days)', 'Restocking Fee (%)', 'Weight (lbs)',
  'Fragile', 'Notes'
];

// Backfill existing rows with empty values for the new columns
for (let i = 1; i < data.length; i++) {
  while (data[i].length < data[0].length) {
    data[i].push('');
  }
}

// Add PROD-2028EE row with full details
data.push([
  'PROD-2028EE',
  'Magnetic Wireless Charging Stand',
  'electronics',
  45,
  'Yes',
  'Mobile Accessories',
  'VoltForge',
  96,
  3.9,
  459,
  'New magnetic wireless charging stand in black for Qi-enabled phones with up to 15W charging. Physical goods accessory with taxable retail pricing and inventory tracking enabled.',
  'None',
  'General Qi-enabled devices (no explicit iPhone 15 listing)',
  3,
  'Yes',
  'No',
  12,
  30,
  0,
  0,
  'No',
  'No variants available. Qi wireless charging compatible up to 15W. iPhone 15 not explicitly listed as compatible but supports Qi standard. Color: Black.'
]);

// Write back
const newWs = XLSX.utils.aoa_to_sheet(data);

// Auto-size columns for readability
const colWidths = data[0].map((_, colIdx) => {
  let max = 10;
  data.forEach(row => {
    const val = row[colIdx] != null ? String(row[colIdx]) : '';
    if (val.length > max) max = Math.min(val.length, 50);
  });
  return { wch: max + 2 };
});
newWs['!cols'] = colWidths;

wb.Sheets['Products'] = newWs;
XLSX.writeFile(wb, '/workspace/testbed/data/product_inventory.xlsx');
console.log('File updated successfully.');

// Verify
const wb2 = XLSX.readFile('/workspace/testbed/data/product_inventory.xlsx');
const ws2 = wb2.Sheets['Products'];
const verify = XLSX.utils.sheet_to_json(ws2, { header: 1 });
console.log('\nUpdated header:', JSON.stringify(verify[0]));
console.log('Total rows (incl header):', verify.length);
const newRow = verify[verify.length - 1];
console.log('\nNew PROD-2028EE row:');
verify[0].forEach((col, i) => {
  console.log('  ' + col + ': ' + JSON.stringify(newRow[i]));
});
"
